package io.github.diodeme.ji.relay;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.security.KeyPairGenerator;
import java.security.Signature;
import java.security.spec.ECGenParameterSpec;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

final class RelayManagementApiTest {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    void ownerClaimInvitationChallengeRevocationAndHostGrantsAreAuthenticated() throws Exception {
        var directory = Files.createTempDirectory("ji-relay-management-");
        try (var relay = new RelayApplication(directory, "127.0.0.1", 0,
                Map.of("JI_RELAY_TERMINAL_BOOTSTRAP", "terminal-only"))) {
            URI root = URI.create("http://127.0.0.1:" + relay.port());
            HttpClient client = HttpClient.newHttpClient();
            JsonNode bootstrap = json(client, request(root.resolve("/api/v1/bootstrap"), Map.of("tenantId", "tenant-1"))
                    .header("X-JI-Terminal-Bootstrap", "terminal-only").build(), 201);
            var owner = p256();
            JsonNode claim = json(client, request(root.resolve("/api/v1/owner/claim"), Map.of(
                    "tenantId", "tenant-1", "pin", bootstrap.path("pin").asText(),
                    "secret", bootstrap.path("secret").asText(), "deviceId", "owner-1",
                    "authAlgorithm", RelayMetadataStore.DEVICE_AUTH_ALGORITHM,
                    "publicKey", Base64.getEncoder().encodeToString(owner.getPublic().getEncoded()))).build(), 201);
            String ownerToken = [REDACTED_CREDENTIAL]"accessToken").asText();
            assertFalse(ownerToken.isBlank());

            JsonNode invitation = json(client, authorized(root.resolve("/api/v1/invitations"), ownerToken,
                    Map.of("hostIds", List.of("host-1"))).build(), 201);
            json(client, authorized(root.resolve("/api/v1/invitations/" + invitation.path("invitationId").asText()
                    + "/confirm"), ownerToken, Map.of("fingerprint", invitation.path("fingerprint").asText())).build(), 200);
            var phone = p256();
            JsonNode accepted = json(client, request(root.resolve("/api/v1/invitations/"
                    + invitation.path("invitationId").asText() + "/accept"), Map.of(
                    "tenantId", "tenant-1", "secret", invitation.path("secret").asText(),
                    "deviceId", "phone-1", "authAlgorithm", RelayMetadataStore.DEVICE_AUTH_ALGORITHM,
                    "publicKey", Base64.getEncoder().encodeToString(phone.getPublic().getEncoded()))).build(), 201);
            assertFalse(accepted.path("accessToken").asText().isBlank());

            JsonNode challenge = json(client, request(root.resolve("/api/v1/auth/challenge"), Map.of(
                    "tenantId", "tenant-1", "deviceId", "phone-1", "connectionId", "connection-1",
                    "authAlgorithm", RelayMetadataStore.DEVICE_AUTH_ALGORITHM)).build(), 201);
            Signature signer = Signature.getInstance("SHA256withECDSA");
            signer.initSign(phone.getPrivate());
            signer.update(DeviceChallengeService.payload("tenant-1", "phone-1", "connection-1",
                    challenge.path("nonce").asText()));
            JsonNode authenticated = json(client, request(root.resolve("/api/v1/auth/verify"), Map.of(
                    "tenantId", "tenant-1", "deviceId", "phone-1", "connectionId", "connection-1",
                    "authAlgorithm", RelayMetadataStore.DEVICE_AUTH_ALGORITHM,
                    "signature", Base64.getEncoder().encodeToString(signer.sign()))).build(), 200);
            assertFalse(authenticated.path("accessToken").asText().isBlank());

            json(client, authorized(root.resolve("/api/v1/hosts/host-1/requested-grants"), ownerToken,
                    Map.of("deviceId", "phone-1", "requestedScopes", List.of("host:request"))).build(), 201);
            JsonNode hostAccess = json(client, authorized(root.resolve("/api/v1/hosts/host-1/access"),
                    ownerToken, Map.of()).build(), 201);
            assertFalse(hostAccess.path("accessToken").asText().isBlank());

            HttpRequest revoke = HttpRequest.newBuilder(root.resolve("/api/v1/devices/phone-1"))
                    .header("Authorization", "Bearer " + ownerToken).DELETE().build();
            json(client, revoke, 200);
            JsonNode devices = json(client, HttpRequest.newBuilder(root.resolve("/api/v1/devices"))
                    .header("Authorization", "Bearer " + ownerToken).GET().build(), 200);
            assertTrue(devices.path("devices").toString().contains("phone-1"));
            assertTrue(devices.path("devices").toString().contains("false"));
            assertFalse(devices.toString().contains(Base64.getEncoder().encodeToString(phone.getPrivate().getEncoded())));
        }
    }

    private static HttpRequest.Builder request(URI uri, Object value) throws Exception {
        return HttpRequest.newBuilder(uri).header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofByteArray(MAPPER.writeValueAsBytes(value)));
    }

    private static HttpRequest.Builder authorized(URI uri, String token, Object value) throws Exception {
        return request(uri, value).header("Authorization", "Bearer " + token);
    }

    private static JsonNode json(HttpClient client, HttpRequest request, int expectedStatus) throws Exception {
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        assertEquals(expectedStatus, response.statusCode(), response.body());
        return MAPPER.readTree(response.body());
    }

    private static java.security.KeyPair p256() throws Exception {
        KeyPairGenerator generator = KeyPairGenerator.getInstance("EC");
        generator.initialize(new ECGenParameterSpec("secp256r1"));
        return generator.generateKeyPair();
    }
}
